import 'dart:io';

import 'package:flutter_test/flutter_test.dart';
import 'package:integration_test/integration_test.dart';

import '../dev/main_test.dart' as app;
import '../dev/test_harness.dart';
import '../dev/test_overlay.dart';
import '../dev/fake_audio_transport.dart';
import 'package:nothingness/models/audio_track.dart';

Future<void> _pumpUntil(
  WidgetTester tester,
  bool Function() condition, {
  Duration timeout = const Duration(seconds: 3),
  Duration step = const Duration(milliseconds: 50),
}) async {
  final deadline = DateTime.now().add(timeout);
  while (DateTime.now().isBefore(deadline)) {
    await tester.pump(step);
    if (condition()) return;
  }
  throw TestFailure('Condition not met within ${timeout.inMilliseconds}ms');
}

void main() {
  IntegrationTestWidgetsFlutterBinding.ensureInitialized();

  testWidgets('queue 10 opus fixtures, shuffle on, next advances exactly once', (
    tester,
  ) async {
    final h = TestHarness.instance;
    h.reset();

    await app.main();
    await tester.pumpAndSettle();

    final dir = Directory('/opt/nothingness/media');
    final fixturePaths = dir
        .listSync()
        .whereType<File>()
        .where((f) => f.path.endsWith('.opus'))
        .map((f) => f.path)
        .toList();

    expect(fixturePaths, hasLength(10));
    final fixtureSet = fixturePaths.toSet();

    await h.setQueue(
      fixturePaths
          .map((p) => AudioTrack(path: p, title: p.split(Platform.pathSeparator).last))
          .toList(),
      startIndex: 0,
      shuffle: true,
    );
    await tester.pumpAndSettle();

    await tester.tap(find.byKey(TestKeys.playPause));
    await _pumpUntil(tester, () {
      return find.textContaining('playing=true').evaluate().isNotEmpty;
    });

    final before = h.transport.currentPath;
    expect(before, isNotNull);
    expect(fixtureSet.contains(before!), isTrue);

    await tester.tap(find.byKey(TestKeys.next));
    await tester.pumpAndSettle();

    final after = h.transport.currentPath;
    expect(after, isNotNull);
    expect(fixtureSet.contains(after!), isTrue);

    // A Next transition should move to a (potentially) different track.
    expect(after, isNot(equals(before)));
  });
}

